CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE role AS ENUM ('SUPER_ADMIN','MERCHANT_OWNER','CASHIER');
CREATE TABLE merchants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outlets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), name text NOT NULL, slug text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_id, slug));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, name text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE merchant_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), user_id uuid NOT NULL REFERENCES users(id), role role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(merchant_id, user_id));
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), outlet_id uuid NOT NULL REFERENCES outlets(id), name text NOT NULL, sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (length(name) > 0));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), outlet_id uuid NOT NULL REFERENCES outlets(id), category_id uuid REFERENCES categories(id), name text NOT NULL, description text NOT NULL DEFAULT '', price integer NOT NULL CHECK (price >= 0), image_url text NOT NULL DEFAULT '', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, group_name text NOT NULL, option_name text NOT NULL, price_delta integer NOT NULL DEFAULT 0, required boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_addons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, name text NOT NULL, price integer NOT NULL CHECK (price >= 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dining_tables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), outlet_id uuid NOT NULL REFERENCES outlets(id), name text NOT NULL, area text NOT NULL DEFAULT '', is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(outlet_id,name));
CREATE TABLE table_qr_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), table_id uuid NOT NULL REFERENCES dining_tables(id), token_hash text NOT NULL UNIQUE, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE table_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), table_id uuid NOT NULL REFERENCES dining_tables(id), token_hash text NOT NULL, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), outlet_id uuid NOT NULL REFERENCES outlets(id), table_id uuid REFERENCES dining_tables(id), idempotency_key text NOT NULL, order_status text NOT NULL CHECK(order_status IN ('NEW_ORDER','IN_PROGRESS','READY_TO_SERVE','COMPLETED','CANCELLED')), payment_status text NOT NULL CHECK(payment_status IN ('UNPAID','PENDING_VERIFICATION','PAID','REFUNDED','CANCELLED')), total_amount integer NOT NULL CHECK(total_amount >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(outlet_id,idempotency_key));
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id uuid REFERENCES products(id), product_name text NOT NULL, unit_price integer NOT NULL CHECK(unit_price >= 0), quantity integer NOT NULL CHECK(quantity > 0), selections jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_item_addons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_item_id uuid NOT NULL REFERENCES order_items(id) ON DELETE CASCADE, addon_name text NOT NULL, price integer NOT NULL CHECK(price >= 0));
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), method text NOT NULL, status text NOT NULL, amount integer NOT NULL CHECK(amount >= 0), verified_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscription_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, monthly_price integer NOT NULL CHECK(monthly_price >= 0), trial_days integer NOT NULL DEFAULT 14 CHECK(trial_days >= 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid NOT NULL REFERENCES merchants(id), plan_id uuid NOT NULL REFERENCES subscription_plans(id), status text NOT NULL CHECK(status IN ('TRIAL','ACTIVE','EXPIRED','SUSPENDED','CANCELLED')), trial_ends_at timestamptz, current_period_ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plan_features (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES subscription_plans(id) ON DELETE CASCADE, feature_key text NOT NULL, is_enabled boolean NOT NULL DEFAULT true, UNIQUE(plan_id,feature_key));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), merchant_id uuid REFERENCES merchants(id), actor_user_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_tenant_idx ON products(merchant_id,outlet_id); CREATE INDEX orders_tenant_idx ON orders(merchant_id,outlet_id,created_at DESC); CREATE INDEX tables_tenant_idx ON dining_tables(merchant_id,outlet_id); CREATE INDEX memberships_user_idx ON merchant_memberships(user_id);
